package org.jfree.chart.renderer.category;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Line2D;
import java.awt.Paint;
import java.awt.Stroke;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.axis.CategoryAxis;
import org.jfree.chart.axis.ValueAxis;
import org.jfree.chart.entity.EntityCollection;
import org.jfree.chart.event.RendererChangeEvent;
import org.jfree.chart.labels.CategoryItemLabelGenerator;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.chart.renderer.category.CategoryItemRendererState;
import org.jfree.chart.util.PaintUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.SerialUtilities;
import org.jfree.data.category.CategoryDataset;
import org.jfree.data.category.StatisticalCategoryDataset;
import org.jfree.data.statistics.StatisticalCategoryDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StatisticalBarRenderer_drawVerticalItem_TriageGen0Test {

    private StatisticalBarRenderer renderer;

    @Mock
    private Graphics2D g2;
    @Mock
    private CategoryItemRendererState state;
    @Mock
    private Rectangle2D dataArea;
    @Mock
    private CategoryPlot plot;
    @Mock
    private CategoryAxis domainAxis;
    @Mock
    private ValueAxis rangeAxis;
    @Mock
    private StatisticalCategoryDataset dataset;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        renderer = new StatisticalBarRenderer() {
            // Overriding protected methods to control behavior for testing
            @Override
            protected int getColumnCount() { return 2; }
            @Override
            protected int getRowCount() { return 2; }
            @Override
            protected double getItemMargin() { return 0.1; }
            @Override
            protected double getLowerClip() { return -10.0; }
            @Override
            protected double getUpperClip() { return 10.0; }
            @Override
            protected Paint getItemPaint(int row, int col) { return Color.BLUE; }
            @Override
            protected Stroke getItemStroke(int row, int col) { return null; }
            @Override
            protected Paint getItemOutlinePaint(int row, int col) { return Color.BLACK; }
            @Override
            protected Stroke getItemOutlineStroke(int row, int col) { return null; }
            @Override
            protected boolean isDrawBarOutline() { return true; }
            @Override
            protected boolean isItemLabelVisible(int row, int col) { return false; }
            @Override
            protected void drawItemLabel(Graphics2D g, StatisticalCategoryDataset ds, int r, int c, 
                                         org.jfree.chart.renderer.category.CategoryItemLabelGenerator gen, 
                                         Rectangle2D b, boolean neg) {}
            @Override
            protected void addItemEntity(org.jfree.chart.entity.EntityCollection ec, StatisticalCategoryDataset ds, 
                                         int r, int c, Rectangle2D b) {}
        };

        // Default Mock behaviors
        when(plot.getDomainAxisEdge()).thenReturn(RectangleEdge.BOTTOM);
        when(plot.getRangeAxisEdge()).thenReturn(RectangleEdge.LEFT);
        when(dataArea.getWidth()).thenReturn(100.0);
        when(domainAxis.getCategoryStart(anyInt(), anyInt(), any(), any())).thenReturn(10.0);
        when(state.getBarWidth()).thenReturn(5.0);
        when(dataset.getMeanValue(anyInt(), anyInt())).thenReturn(5.0);
        when(dataset.getStdDevValue(anyInt(), anyInt())).thenReturn(1.0);
        when(rangeAxis.valueToJava2D(anyDouble(), any(), any())).thenReturn(10.0);
    }

    // Helper to access protected method
    private void invokeDrawVerticalItem(Graphics2D g2, CategoryItemRendererState state, Rectangle2D dataArea, 
                                       CategoryPlot plot, CategoryAxis domainAxis, ValueAxis rangeAxis, 
                                       StatisticalCategoryDataset dataset, int row, int column) {
        renderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, row, column);
    }

    @Test
    public void testDrawVerticalItem_StandardCase() {
        // Case 9-12: lclip < 0 < uclip, value in range
        invokeDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
        verify(g2, atLeastOnce()).draw(any(Line2D.class));
    }

    @Test
    public void testDrawVerticalItem_UclipZero_ValueVisible() {
        // Case 1-4: uclip <= 0, value < uclip (e.g. value -5, uclip -2)
        // We need to redefine the renderer behavior via a subclass or reflection if we want to change clips.
        // Since we used an anonymous class in setUp, we will simulate via a new instance for specific clip tests.
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getUpperClip() { return -2.0; }
            @Override protected double getLowerClip() { return -10.0; }
            @Override protected int getRowCount() { return 1; }
            @Override protected int getColumnCount() { return 1; }
            @Override protected Paint getItemPaint(int r, int c) { return Color.RED; }
            @Override protected boolean isDrawBarOutline() { return false; }
            @Override protected Paint getItemOutlinePaint(int r, int c) { return Color.BLACK; }
            @Override protected Stroke getItemOutlineStroke(int r, int c) { return null; }
            @Override protected boolean isItemLabelVisible(int r, int c) { return false; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(-5.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_UclipZero_ValueNotVisible() {
        // Case 1-4: uclip <= 0, value >= uclip
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getUpperClip() { return -2.0; }
            @Override protected double getLowerClip() { return -10.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(0.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_LclipZero_ValueInRange() {
        // Case 5-8: lclip <= 0
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getLowerClip() { return 0.0; }
            @Override protected double getUpperClip() { return 10.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_LclipZero_ValueAtUclip() {
        // Case 5-8: lclip <= 0, value >= uclip
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getLowerClip() { return 0.0; }
            @Override protected double getUpperClip() { return 5.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(10.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2).fill(any(Rectangle2D.class)); // value becomes uclip
    }

    @Test
    public void testDrawVerticalItem_LclipZero_ValueAtLclip() {
        // Case 5-8: lclip <= 0, value <= lclip
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getLowerClip() { return 0.0; }
            @Override protected double getUpperClip() { return 10.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(-5.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2).fill(any(Rectangle2D.class)); // value becomes lclip
    }

    @Test
    public void testDrawVerticalItem_LclipPositive_ValueNotVisible() {
        // Case 9-12: lclip > 0, value <= lclip
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getLowerClip() { return 5.0; }
            @Override protected double getUpperClip() { return 10.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(2.0);

        customRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_OutlineAndEntity() {
        // Test outline drawing and entity collection
        org.jfree.chart.entity.EntityCollection entities = mock(org.jfree.chart.entity.EntityCollection.class);
        when(state.getEntityCollection()).thenReturn(entities);
        when(state.getBarWidth()).thenReturn(10.0); // > 3 to trigger outline

        invokeDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2).draw(any(Rectangle2D.class)); // Outline
        verify(g2).draw(any(Line2D.class)); // Error bar
    }

    @Test
    public void testDrawVerticalItem_ErrorIndicatorCustom() {
        Paint customPaint = Color.GREEN;
        Stroke customStroke = null; // Actual stroke object would be needed for full check
        renderer.setErrorIndicatorPaint(customPaint);
        renderer.setErrorIndicatorStroke(customStroke);

        invokeDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2).setPaint(customPaint);
        verify(g2).setStroke(customStroke);
    }

    @Test
    public void testDrawVerticalItem_SeriesGapCalculation() {
        // Test the seriesGap logic for seriesCount > 1
        StatisticalBarRenderer multiSeriesRenderer = new StatisticalBarRenderer() {
            @Override protected int getRowCount() { return 2; }
            @Override protected int getColumnCount() { return 2; }
            @Override protected double getItemMargin() { return 0.5; }
        };

        multiSeriesRenderer.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 1, 0);
        // Verification of rectX is implicit if no exception occurs and g2 is called
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }
}
